import { DURATION_TOLERANCE, rankCandidates, wantedFromCandidate } from './resolver/match.js';
import type { Candidate, SearchProvider, Source, StreamInfo, StreamResult } from './resolver/types.js';

export const SOURCE_UNAVAILABLE = 'Источник сейчас недоступен';

/** Bounds even providers that ignore cancellation; late rejection is consumed by Promise.race. */
export async function bounded<T>(fn: () => Promise<T>, ms: number): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([Promise.resolve().then(fn), new Promise<never>((_, reject) => {
      timer = setTimeout(() => reject(new Error('source timeout')), ms);
    })]);
  } finally { clearTimeout(timer); }
}

export type PlaybackResult = { ok: true; stream: StreamInfo; playing: Candidate; fallback: boolean }
  | { ok: false; message: string };

/** Try selected track, then only the other source. Never retry a known failed source. */
export async function playbackFallback(candidate: Candidate, o: {
  direct: (c: Candidate) => Promise<StreamResult>;
  providers: SearchProvider[];
  failedSource?: Source;
  timeoutMs?: number;
  onFailure?: (message: string) => void;
}): Promise<PlaybackResult> {
  const timeout = o.timeoutMs ?? 6000;
  const deadline = Date.now() + timeout * 2;
  const attempt = <T>(fn: () => Promise<T>) => bounded(fn, Math.max(1, Math.min(timeout, deadline - Date.now())));
  let preview = false;
  if (!o.failedSource) {
    try {
      const r = await attempt(() => o.direct(candidate));
      if (r.ok) return { ok: true, stream: r.stream, playing: candidate, fallback: false };
      preview = r.reason === 'preview';
      o.onFailure?.(`${candidate.source}: ${r.reason}`);
    } catch { o.onFailure?.(`${candidate.source}: error or timeout`); }
  }
  const failed = o.failedSource ?? candidate.source;
  const wanted = wantedFromCandidate(candidate, !preview);
  // A failed replacement means both sources have already been tried for this playback.
  if (o.failedSource && o.failedSource !== candidate.source) return { ok: false, message: SOURCE_UNAVAILABLE };
  const provider = o.providers.find(p => p.source !== failed && p.source !== 'local');
  if (!provider) return { ok: false, message: SOURCE_UNAVAILABLE };
  const ctrl = new AbortController();
  try {
    const found = await attempt(() => provider.search(`${wanted.artist} ${wanted.title}`, 5, ctrl.signal));
    const good = rankCandidates(found, wanted).filter(s => !s.rejected && s.titleScore >= 0.8 && s.artistScore >= 0.8);
    for (const s of good.slice(0, 2)) {
      if (Date.now() >= deadline) break;
      try {
        const r = await attempt(() => o.direct(s.candidate));
        if (!r.ok || !r.stream.duration) { o.onFailure?.(`${provider.source}: unavailable audio`); continue; }
        if (wanted.duration && Math.abs(r.stream.duration - wanted.duration) > DURATION_TOLERANCE) { o.onFailure?.(`${provider.source}: duration mismatch`); continue; }
        return { ok: true, stream: r.stream, playing: s.candidate, fallback: true };
      } catch { o.onFailure?.(`${provider.source}: error or timeout`); }
    }
  } catch { o.onFailure?.(`${provider.source}: search error or timeout`); }
  finally { ctrl.abort(); }
  return { ok: false, message: SOURCE_UNAVAILABLE };
}
